shell_commands:
node -e "
import('ajv').then(({default: AjvModule}) => {
  const Ajv = AjvModule.default;
  const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
  const validate = ajv.compile({
    type: 'object',
    properties: {
      location: {type: 'string'},
      units: {type: 'string', enum: ['celsius', 'fahrenheit']},
      filters: {
        type: 'object',
        properties: {count: {type: 'number'}},
        required: ['count']
      }
    },
    required: ['location']
  });
  validate({});
  console.log('missing required:', validate.errors);
  validate({location: 12345, units: 'kelvin', filters: {}});
  console.log('type + enum + nested required:', validate.errors);
});
" && head -n 90 node_modules/ajv/dist/types/index.d.ts
